#!/usr/bin/env python
"""网格 + 材料/边界/载荷 -> CalculiX 计算 deck（job.inp）

用法： python deck.py --job C:\\cae\\jobs\\job-0001

数据来源：
  * 网格段（*NODE/*ELEMENT/*ELSET）：gmsh 导出的 part.inp，原样保留；
  * 节点集合：mesh.py 生成的 groups.json（按坐标平面精确筛选的节点号），
    写成显式 *NSET 节点列表 —— 这样载荷按真实受载节点数均摊，
    也不会出现 Gmsh Abaqus .inp 只有 ELSET 的问题。

本脚本只"追加"材料、截面、分析步、边界、载荷、输出请求；纯 string.Template，无第三方依赖。
"""
from __future__ import annotations

import argparse
import json
import math
import sys
from pathlib import Path
from string import Template

DECK_HEAD = """\
** ---- generated by deck.py (mm-N-MPa) ----
** node sets come from gmsh via groups.json (exact node ids)
"""

DECK_BODY = Template(
    """
*MATERIAL, NAME=${mat_name}
*ELASTIC
${E}, ${nu}
*DENSITY
${rho}
*SOLID SECTION, ELSET=${solid}, MATERIAL=${mat_name}
** ---- step ----
*STEP
*${analysis}
*BOUNDARY
NFIXED, 1, 3, 0.0
*CLOAD
NLOAD, 1, ${fx}
NLOAD, 2, ${fy}
NLOAD, 3, ${fz}
*NODE FILE
U
*EL FILE
S, E
*END STEP
"""
)

ANALYSIS_MAP = {
    "static": "STATIC",
    "frequency": "FREQUENCY",
    "buckle": "BUCKLE",
    "heat": "HEAT TRANSFER, STEADY STATE",
}


def write_nset(name: str, values: list[int]) -> str:
    if not values:
        raise SystemExit(f"ERROR: 节点集合 {name} 为空")
    lines = [f"*NSET, NSET={name}"]
    for i in range(0, len(values), 10):
        lines.append(", ".join(str(v) for v in values[i : i + 10]))
    return "\n".join(lines) + "\n"


def find_element_set(inp_text: str) -> str:
    """从 part.inp 里找体单元集合名（gmsh 默认写 ELSET=Volume1）。"""
    for line in inp_text.splitlines():
        upper = line.upper()
        if upper.startswith("*ELEMENT") and "TYPE=C3D" in upper:
            for part in line.split(","):
                if "ELSET" in part.upper():
                    return part.split("=")[-1].strip()
    return "SOLID"


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--job", required=True)
    args = ap.parse_args()

    job_dir = Path(args.job).resolve()
    params = json.loads((job_dir / "params.json").read_text(encoding="utf-8-sig"))
    inp_path = job_dir / "part.inp"
    groups_path = job_dir / "groups.json"
    if not inp_path.exists():
        print(f"ERROR: 缺少 {inp_path}，先跑 mesh.py", file=sys.stderr)
        return 2
    if not groups_path.exists():
        print(f"ERROR: 缺少 {groups_path}，请用当前版本的 mesh.py 重新生成", file=sys.stderr)
        return 2

    groups = json.loads(groups_path.read_text(encoding="utf-8-sig"))
    fixed_nodes = groups.get("FIXED", {}).get("nodes", [])
    load_nodes = groups.get("LOAD", {}).get("nodes", [])
    if not fixed_nodes or not load_nodes:
        print("ERROR: groups.json 中 FIXED/LOAD 节点为空", file=sys.stderr)
        return 3

    mat = params.get("material", {})
    bc = params.get("bc", {})
    solver = params.get("solver", {})
    analysis = ANALYSIS_MAP.get(str(solver.get("analysis", "static")).lower(), "STATIC")

    direction = bc.get("load_direction", [0, 0, -1])
    total = float(bc.get("load_total_N", 0.0))
    norm = math.sqrt(sum(float(v) ** 2 for v in direction)) or 1.0
    per_node = total / len(load_nodes)
    fx, fy, fz = [per_node * float(v) / norm for v in direction]

    raw = inp_path.read_text(encoding="utf-8", errors="replace")
    solid = find_element_set(raw)
    body = DECK_BODY.substitute(
        mat_name=mat.get("name", "steel"),
        E=float(mat.get("E", 210000.0)),
        nu=float(mat.get("nu", 0.3)),
        rho=float(mat.get("rho", 7.85e-9)),
        solid=solid,
        analysis=analysis,
        fx=f"{fx:.6g}",
        fy=f"{fy:.6g}",
        fz=f"{fz:.6g}",
    )

    deck = (
        raw.rstrip()
        + "\n"
        + DECK_HEAD
        + write_nset("NFIXED", fixed_nodes)
        + write_nset("NLOAD", load_nodes)
        + body
    )
    job_inp = job_dir / "job.inp"
    job_inp.write_text(deck, encoding="utf-8")

    info = {
        "deck": str(job_inp),
        "solid_elset": solid,
        "fixed_nodes": len(fixed_nodes),
        "load_nodes": len(load_nodes),
        "force_per_node_N": [round(fx, 6), round(fy, 6), round(fz, 6)],
        "analysis": analysis,
    }
    (job_dir / "deck.json").write_text(json.dumps(info, indent=2, ensure_ascii=False), encoding="utf-8")
    print(json.dumps(info, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
